 import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, mix, smoothstep, color, float, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PointLight, Color, PlaneGeometry, Shape, ExtrudeGeometry, BoxGeometry, Box3, Vector3 } = ctx.THREE;

  const root = new Group();
  root.name = config.id || 'home-thumbnail';

  const timelines = [];

  const ink = new Color('#16161d');
  const paper = new Color('#e8ecf2');
  const accent = new Color('#ff2a38');
  const surface = new Color('#0b0b10');

  const cardW = 2.0;
  const cardH = 1.25;
  const cardD = 0.08;
  const radius = 0.08;

  function roundedRectShape(w, h, r) {
    const hw = w * 0.5;
    const hh = h * 0.5;
    const s = new Shape();
    s.moveTo(-hw + r, hh);
    s.lineTo(hw - r, hh);
    s.quadraticCurveTo(hw, hh, hw, hh - r);
    s.lineTo(hw, -hh + r);
    s.quadraticCurveTo(hw, -hh, hw - r, -hh);
    s.lineTo(-hw + r, -hh);
    s.quadraticCurveTo(-hw, -hh, -hw, -hh + r);
    s.lineTo(-hw, hh - r);
    s.quadraticCurveTo(-hw, hh, -hw + r, hh);
    return s;
  }

  const bodyGeo = new ExtrudeGeometry(roundedRectShape(cardW, cardH, radius), {
    depth: cardD,
    bevelEnabled: true,
    bevelThickness: 0.015,
    bevelSize: 0.015,
    bevelSegments: 3,
    curveSegments: 16,
  });
  const bodyMat = new MeshPhysicalNodeMaterial({
    color: surface,
    roughness: 0.55,
    metalness: 0.35,
    clearcoat: 0.15,
  });
  const cardBody = new Mesh(bodyGeo, bodyMat);
  cardBody.castShadow = true;
  cardBody.receiveShadow = true;
  root.add(cardBody);

  const gradNode = mix(color('#16161d'), color('#0b0b10'), smoothstep(0, 1, uv().y));
  const bgGeo = new PlaneGeometry(cardW - 0.16, cardH - 0.16);
  const bgMat = new MeshBasicNodeMaterial({ transparent: false });
  bgMat.colorNode = gradNode;
  const bgPlane = new Mesh(bgGeo, bgMat);
  bgPlane.position.z = cardD + 0.005;
  root.add(bgPlane);

  const stripH = 0.22;
  const stripGeo = new BoxGeometry(cardW - 0.16, stripH, 0.02);
  const stripMat = new MeshPhysicalNodeMaterial({ color: ink, roughness: 0.6, metalness: 0.3 });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -cardH * 0.5 + stripH * 0.5 + 0.08, cardD + 0.015);
  root.add(strip);

  const edgeGeo = new BoxGeometry(cardW - 0.16, 0.015, 0.025);
  const edgeMat = new MeshPhysicalNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 0.5,
    roughness: 0.4,
    metalness: 0.1,
  });
  const accentEdge = new Mesh(edgeGeo, edgeMat);
  accentEdge.position.set(0, strip.position.y + stripH * 0.5 + 0.012, cardD + 0.025);
  root.add(accentEdge);

  const shadowGeo = new PlaneGeometry(1.6, 1.0);
  const shadowUV = uv().sub(vec2(0.5, 0.5)).mul(vec2(2.0, 2.0));
  const shadowAlpha = float(1.0).sub(smoothstep(float(0.0), float(1.0), length(shadowUV)));
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = shadowAlpha;
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -0.1, cardD + 0.005);
  root.add(shadowPlane);

  const mediaGroup = new Group();
  mediaGroup.position.set(0, 0.05, cardD + 0.12);
  root.add(mediaGroup);

  const idleTl = gsap.to(mediaGroup.rotation, { z: 6.283185307, duration: 60, repeat: -1, ease: 'none' });
  timelines.push(idleTl);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const model = gltf.scene;
      model.updateMatrixWorld(true);

      const box = new Box3().setFromObject(model);
      const size = box.getSize(new Vector3());
      const center = box.getCenter(new Vector3());
      const maxDim = Math.max(size.x, size.y, size.z || 1);
      const target = 0.65;
      const s = target / maxDim;

      model.scale.setScalar(s);
      model.position.sub(center.clone().multiplyScalar(s));
      model.traverse((child) => {
        if (child.isMesh) {
          child.castShadow = true;
          child.receiveShadow = true;
        }
      });

      mediaGroup.add(model);

      gsap.from(model.scale, {
        x: 0.001,
        y: 0.001,
        z: 0.001,
        duration: 0.7,
        ease: 'back.out(1.4)',
      });
    });
  }

  const keyLight = new PointLight(paper, 1.2, 8);
  keyLight.position.set(1.0, 1.2, 1.6);
  root.add(keyLight);

  const rimLight = new PointLight(accent, 0.8, 8);
  rimLight.position.set(-1.0, 0.5, 1.4);
  root.add(rimLight);

  const fillLight = new PointLight(paper, 0.3, 8);
  fillLight.position.set(0, -0.8, 1.0);
  root.add(fillLight);

  function lift(active) {
    gsap.to(root.position, {
      z: active ? 0.15 : 0,
      duration: 0.35,
      ease: 'power2.out',
      overwrite: 'auto',
    });
    gsap.to(accentEdge.material, {
      emissiveIntensity: active ? 1.4 : 0.5,
      duration: 0.35,
      ease: 'power2.out',
      overwrite: 'auto',
    });
  }

  function press(active) {
    gsap.to(root.scale, {
      x: active ? 0.97 : 1,
      y: active ? 0.97 : 1,
      z: active ? 0.97 : 1,
      duration: 0.12,
      ease: 'power2.out',
      overwrite: 'auto',
    });
  }

  root.userData.handlers = {
    pointerEnter: () => lift(true),
    pointerLeave: () => {
      lift(false);
      press(false);
    },
    pointerDown: () => press(true),
    pointerUp: () => press(false),
    click: () => ctx.emit('hub-home.select', { id: config.id, hub: 'hub-home', node: root }),
  };

  root.userData.cleanup = () => {
    timelines.forEach((tl) => { tl.kill(); });
    root.userData.handlers = {};

    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}
